import {p,code,table,qa,refs,section,warn} from './lesson-helpers.mjs';
const guide=(slug,title,heading,intro,prerequisites,outcome,sections)=>({slug,title,heading,intro,definition:intro,prerequisites,outcome,sections});
const s=section;
export const practiceGuides=[
guide('decision-guides','Architecture Decision Guides','Choose a mechanism by the guarantee it must supply','An architecture decision connects a requirement to a mechanism, states the rejected alternatives, and identifies the evidence that would justify revisiting it.','Read <a href="databases.html#reasoning-path">database correctness</a>, <a href="messaging.html#reasoning-path">message boundaries</a> and <a href="consistency.html#reasoning-path">consistency</a>.','Write a decision that survives a concrete failure scenario, rather than selecting a product by familiarity.',[
s('problem','Start with one decision, not the whole stack',p('The checkout service must reserve stock before confirming an order. “Use PostgreSQL and Kafka” is not yet a decision: neither name explains which operation prevents overselling. Write the rule first: for a given SKU, the sum of active reservations must never exceed available stock. Then locate the authority that can enforce the rule under concurrent requests. A local conditional update may be sufficient; a distributed workflow becomes relevant only when ownership crosses a commit boundary.')+p('A useful decision record contains context, required guarantees, options, chosen approach, failure behavior, operational cost and revisit triggers. Record what was measured and what remains an assumption. An assumption such as “one database can serve the next year” needs an explicit load-test or utilization trigger, not an indefinitely valid promise.')),
s('requirements','Separate hard rules from preferences',table(['Input','Example','Effect on choice'],[['Invariant','No negative stock','Needs atomic enforcement at the stock authority.'],['Freshness','Browse availability may lag five seconds','Permits a projection for browsing, not final reservation.'],['Target','Illustrative p95 reservation under 150 ms','Constrains coordination and critical-path dependencies.'],['Constraint','Team operates PostgreSQL and EKS','Makes an unfamiliar store an additional cost requiring evidence.']])+p('Preferences can be traded. An invariant cannot be silently weakened to reach a latency target. If requirements conflict, expose the conflict to product owners through concrete outcomes: “the page may show a seat that another buyer has just claimed” differs from “two buyers receive confirmed ownership.”')),
s('storage','SQL or NoSQL: derive from operations',table(['Choose when','Candidate','Prove before adoption'],[['Related writes and local invariants dominate','PostgreSQL / RDS','Constraints, transaction contention, indexes, pool capacity and restore.'],['Known keyed operations and distributed managed capacity dominate','DynamoDB','Partition distribution, conditional mutation, transaction limits and exact read path.'],['Aggregate-shaped documents change together','MongoDB','Document size, update atomicity, index cost and cross-document rules.'],['Text relevance and faceting dominate','Search projection','Freshness, replay, deletion and source-of-truth separation.']])+p('Do not compare product categories in the abstract. Express a real operation, expected key distribution and transaction scope. A single hot inventory key remains a coordination point in any store. Splitting that key requires a business allocation protocol, not merely a new database brand.')),
s('communication','REST or messaging: start with completion semantics',p('Use a synchronous request when the caller needs a bounded immediate answer and the dependency fits the deadline. Use a durable asynchronous handoff when acceptance can be separated from completion. The API must then expose pending, terminal and recovery states. A message bus does not make the caller’s original operation complete.')+table(['Question','Synchronous choice','Asynchronous choice'],[['Must the caller learn a final result now?','Return the result within a bounded deadline.','Return acceptance plus a durable operation ID when deferral is allowed.'],['What survives a process crash?','Durable local operation state and retry identity.','Durable handoff plus deduplication and replay policy.'],['What does coupling cost?','Availability and latency of required dependencies.','Schema evolution, backlog, eventual completion and recovery ownership.']])+p('Spring HTTP clients, Kafka clients and SQS SDKs implement communication. Application state machines still own business completion. Retry libraries cannot decide whether another charge is safe.')),
s('coordination','Transaction, saga, or reservation?',p('Prefer a local transaction when the relevant facts share one authority and commit boundary. When independent authorities are necessary, describe the intermediate states first. A saga coordinates local commits and recovery; a reservation temporarily allocates a resource while later steps run. A saga may use reservations, and neither makes remote effects part of a local ACID transaction.')+p('For booking, reserve a seat until a defined expiry. If payment completes after expiry, a coordinator must apply a declared rule: obtain a new reservation if allowed, otherwise refund or route to manual recovery. A queue, retry annotation or distributed lock cannot decide that business policy.')),
s('worked','Worked decision record: protect inventory',p('<strong>Context:</strong> one inventory authority; requests can repeat; payment is external. <strong>Decision:</strong> reserve using a positive-quantity conditional SQL update and insert the reservation and outbox in one transaction. Scope a unique operation ID by tenant. Keep payment outside the lock-holding transaction and persist its unknown/terminal states.')+p('<strong>Rejected:</strong> Java read-then-write, because concurrent buyers can both pass; a Redis-only lock, because ownership can expire while work continues and it does not itself make SQL mutations atomic; moving inventory to another store without a measured need, because it adds migration work without removing the invariant.')+p('<strong>Trade-offs:</strong> hot SKUs serialize, reservations need expiry and reconciliation, and payment completion can race cancellation. <strong>Evidence:</strong> race tests, affected-row checks, expiry/payment reconciliation and a contention benchmark. <strong>Revisit:</strong> measured hot-key throughput exceeds safe capacity or independent domain ownership becomes necessary.')),
s('interview','Defend the decision',qa([['Intermediate','Why not choose the fastest database?','A benchmark without the actual invariant, key distribution and failure mode can measure an irrelevant operation. Establish required semantics first, then compare sustainable throughput and operational cost.'],['Advanced','When is a distributed lock justified?','When exclusive ownership is necessary and a defined lease/fencing protocol can prevent obsolete owners from acting. Prefer authoritative conditional mutations when they already enforce the invariant; a lock alone is not durable effect deduplication.'] ])),
s('references','Read with a question',refs([['https://docs.aws.amazon.com/prescriptive-guidance/latest/architectural-decision-records/welcome.html','AWS architecture decision records','structure a durable decision and its consequences.'],['https://www.postgresql.org/docs/current/transaction-iso.html','PostgreSQL isolation','check which anomalies a proposed protocol permits.'],['https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html','Saga orchestration','inspect distributed recovery rather than assuming rollback.']]))
]),
guide('failure-case-studies','Production Failure Case Studies','Investigate what failed before changing the system','A failure investigation reconstructs the observed business outcome from durable state and telemetry, tests competing hypotheses, and distinguishes immediate mitigation from permanent repair.','Read <a href="observability.html#reasoning-path">evidence and identity</a> and <a href="reliability.html#reasoning-path">unknown outcomes</a>. These are fictional teaching cases, not reports of actual incidents.','Build a timeline, select safe mitigations and define evidence of recovery.',[
s('problem','Use a repeatable investigation method',p('Start with customer impact and the invariant at risk. Preserve a time window, affected population and identities before logs rotate. Form at least two plausible explanations; an alarming graph alone is not causation. Compare changes, dependency behavior and business state. Mitigate using the smallest action that protects correctness, then verify recovery through completed business outcomes.')+p('Use this sequence in each case: symptom → evidence → competing hypotheses → discriminating check → mitigation → repair → recovery proof. Do not replay work merely because a queue is quiet or an HTTP call timed out. First establish whether the effect already happened.')),
s('cache-storm','Case 1: a cache expiry becomes a database incident',p('<strong>Symptom:</strong> catalog p99 rises after a popular collection expires. Application CPU is moderate; database connections and lease wait spike. <strong>Hypotheses:</strong> a query regression, database resource loss, or synchronized misses. Correlate expiry/miss rate, active queries, query plans and the deployment timeline. Stable plans plus a sudden concentration of identical reads support the stampede hypothesis.')+p('<strong>Mitigation:</strong> constrain refill and fallback concurrency, serve permitted stale catalog data, and shed lower-priority work. Increasing every pod’s connection pool would add pressure. <strong>Repair:</strong> per-key request coalescing, TTL jitter where appropriate, bounded refresh and admission control. Local single-flight reduces duplication within one process; fleet-wide behavior still needs analysis.')+p('<strong>Recovery proof:</strong> source query load returns within its budget, oldest waits shrink, cache freshness stays within its contract, and checkout success does not degrade. A recovered hit ratio alone is insufficient. See <a href="caching.html#reasoning-path">the cache race explanation</a>.')),
s('duplicate-payment','Case 2: a customer reports two charges',p('<strong>Symptom:</strong> two provider charges map to one intended checkout. <strong>Hypotheses:</strong> duplicated HTTP attempts, webhook replay, or reconciliation creating a fresh provider operation. Compare tenant, order ID, local operation key, request fingerprint and provider operation IDs across attempts. Trace IDs can differ during a legitimate retry and cannot establish business uniqueness.')+p('<strong>Discriminating check:</strong> did an earlier call time out after provider success, followed by a call with a new key? If so, local uniqueness may be intact while the remote boundary is unprotected. <strong>Mitigation:</strong> stop unsafe automatic reissue for affected states, reconcile provider records and handle refunds under the established business policy. Do not bulk-mark unknown payments failed.')+p('<strong>Repair:</strong> stable provider identity, durable UNKNOWN state, bounded reconciliation and explicit retention behavior. <strong>Recovery proof:</strong> every affected local operation maps to its known provider outcome, unresolved cases have owners, and crash-window tests no longer produce a second effect.')),
s('backlog','Case 3: a healthy broker hides a stalled business flow',p('<strong>Symptom:</strong> paid orders remain unfulfilled while broker delivery is healthy. <strong>Hypotheses:</strong> publication failed, consumers lost capacity, a poison schema repeats, or remote fulfillment is slow. Compare oldest business-state age, outbox lag, delivery rate, consumer commit rate and quarantine records. Queue depth alone may fall when messages move to a dead-letter queue.')+p('<strong>Mitigation:</strong> isolate the incompatible population, retain event identity and restore a compatible reader. Replaying without a durable consumer guard can create duplicate shipments. <strong>Repair:</strong> compatibility checks, per-event failure isolation and an explicit replay protocol. Decide whether preserving order for an aggregate requires pausing later events rather than skipping the bad one.')+p('<strong>Recovery proof:</strong> affected paid orders reach the correct terminal fulfillment state, oldest age drains and replay does not duplicate shipment identity. See <a href="messaging.html#reasoning-path">acknowledgement boundaries</a>.')),
s('worked','Case 4: a successful rollout causes intermittent errors',p('Version B writes a new status that version A cannot parse. Probes pass because they never read that state. Errors appear only on A pods and only for recently changed orders. Distinguish this from network flakiness by joining version, state and failure class with bounded telemetry dimensions.')+p('Disable the incompatible writer feature if that is safe, retain evidence and deploy a tolerant reader. Rolling all pods back to A can spread the failure because new data survives. Prevent recurrence using expand/contract sequencing, mixed-version contract tests and backward-compatible readers before writers. Recovery requires checking the already-written population, not just the next health probe.')),
s('interview','Incident interview follow-ups',qa([['Intermediate','Why not restart everything first?','It can destroy evidence, multiply cold-start load and replay work without knowing previous outcomes. Protect the invariant and collect minimal decisive evidence; restart when there is a supported hypothesis that it helps.'],['Advanced','How do you prove the mitigation worked?','Observe restored customer outcomes, bounded backlog age and correctness of affected records over an explicit interval. Resource graphs alone may recover while business work stays stranded.'] ])),
s('references','Primary reading',refs([['https://sre.google/sre-book/effective-troubleshooting/','Google SRE troubleshooting','hypothesis-driven investigation.'],['https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html','SQS dead-letter queues','isolation, retention and redrive considerations.'],['https://opentelemetry.io/docs/concepts/signals/','OpenTelemetry signals','understand what each signal can establish.']]))
]),
guide('capacity-cost','Capacity & Cost Estimation','Turn workload assumptions into a capacity argument','Capacity estimation translates a workload and service-time model into resource demand, headroom and cost ranges. It is a hypothesis to validate with measurement, not a prediction guaranteed by arithmetic.','Read <a href="scalability.html#reasoning-path">throughput and waiting</a>, <a href="databases.html#indexes">indexes</a> and <a href="rate-limiting.html#reasoning-path">concurrency</a>.','Calculate a baseline, expose skew and failure headroom, and construct an AWS cost model without relying on stale prices.',[
s('problem','Define the units before calculating',p('Suppose a shop serves 2 million active users per day, each making 20 eligible reads. That is 40 million reads/day, or about 463 requests/second averaged over 86,400 seconds. An assumed 8× peak gives roughly 3,704 requests/second. The peak multiplier is an assumption requiring traffic evidence. Reads and writes must be modeled separately; a ten-item batch request is one HTTP request but potentially many database operations.')+p('State whether measurements count attempts, successful operations or useful business completions. Retries increase attempts without increasing useful work. Separate cache hits, misses and background refresh from user request volume. Use decimal GB or binary GiB consistently and specify whether replication and indexes are included.')),
s('concurrency','Derive simultaneous work and headroom',p('Little’s Law relates average work in a stable measured system: L = λ × W. At 3,704 admitted requests/second and 0.120 seconds average response time, average in-flight work is about 445. This is not a p99 prediction, and substituting p99 latency into the formula does not produce p99 concurrency. Burst and tail behavior require measurement or a queueing model.')+p('If one replica sustains 350 requests/second at the required latency under the representative mix, twelve replicas supply nominal capacity above the example peak. To remain under 60% of that tested maximum during peak, ceil(3704 / (350 × 0.6)) gives 18 replicas. This only works if shared dependencies sustain that rate. Losing six of eighteen replicas leaves about 88% nominal utilization: acceptable failure capacity must be tested explicitly, not inferred from the normal 60% target.')),
s('storage','Estimate durable bytes and write amplification',p('At one million new orders/day and 2 KB serialized data/order, the base input is approximately 2 GB/day and 730 GB/year using decimal units. Indexes, row overhead, revisions, retention, replicas, backups and telemetry are additional. Apply explicit measured multipliers rather than calling the base figure “database size.” A replication factor is not a backup strategy.')+p('With an illustrative index/overhead multiplier of 1.8, the primary live dataset is about 1.314 TB/year before retention effects. Three live copies would be about 3.942 TB collectively, but billable storage semantics depend on the service. Do not multiply an AWS line item again if replication is already included in that product’s billed unit.')),
s('bottlenecks','Estimate cache, backlog and partitions',table(['Calculation','Illustrative result','Qualification'],[['DB reads = incoming reads × miss fraction','3704 × 0.05 ≈ 185 reads/s','Assumes every miss causes one read; include stampedes, writes and refresh.'],['Queue drain = backlog / (completion − arrival)','120000 / (900 − 500) = 300 s','Only if both rates remain stable and retries do not consume the margin.'],['Memory payload = concurrent work × retained bytes','445 × 64 KB ≈ 28.5 MB','Excludes runtime, stacks, buffers, object overhead and idle resources.'],['Connections = replicas × pool maximum','18 × 20 = 360 possible connections','Compare with database capacity and operational reserve.']])+p('Partition count is constrained by sustainable per-partition throughput, ordering and key skew, not simply aggregate volume. A single hot key may remain serialized. Consumer count above available parallel work cannot force additional throughput.')),
s('cost','Build a price-independent AWS model',p('Use current regional quotes when making a budget. This lesson intentionally uses no asserted current AWS prices. Enumerate units, then attach verified prices: compute instance-hours or vCPU/memory time, database compute/storage/I/O, request charges, transfer, NAT processing, logs, traces, backups and cross-region replication. Include minimum provisioned capacity and operational environments.')+code('monthly_cost = compute_hours * compute_unit_price\n             + storage_GB_month * storage_unit_price\n             + billable_requests * request_unit_price\n             + transfer_GB * transfer_unit_price\n             + telemetry + backups + other_fixed_costs')+p('Use low/base/high demand and retention scenarios. Compare cost per useful completed order alongside total spend; retries, failed work and excessive logging can make a service more expensive while traffic looks unchanged. Managed-service cost may be higher per unit while reducing operating effort; record that separately rather than inventing a precise labor saving.')),
s('worked','Worked review: defend a peak-day plan',p('Begin with the 3,704 read/s assumption. Validate the 350 read/s replica figure under realistic cache hit ratio, tenant skew, payload size and dependency behavior. Test with one availability-zone share unavailable. Cap database connections and admissions, pre-scale where startup delay exceeds burst tolerance, and define what work is shed first.')+p('Then repeat with 20% cache misses and a dependency slowdown. The database read estimate becomes about 741/s before write/refresh overhead; CPU scaling alone cannot establish this is safe. Publish the measured saturation point, latency distribution, useful completion rate and cost range. Revise the plan when a model assumption changes.')),
s('interview','Estimation interview',qa([['Foundational','Why start with daily traffic if it is not the peak?','It supplies a reproducible baseline and exposes assumptions. Apply and justify a peak model rather than presenting the average as capacity.'],['Advanced','Why is 50% fleet CPU not proof of spare capacity?','A database, hot key, connection pool or single-threaded stage may be saturated. Aggregate CPU also hides skew and failure-domain concentration. Identify the limiting resource for the target operation.'] ])),
s('references','Sources for verification',refs([['https://aws.amazon.com/architecture/well-architected/','AWS Well-Architected','performance, reliability and cost trade-offs.'],['https://calculator.aws/','AWS Pricing Calculator','apply current region-specific prices to explicit units.'],['https://sre.google/sre-book/handling-overload/','Google SRE overload','measure overload and admission behavior.']]))
]),
guide('java-spring-internals','Java & Spring Architecture Internals','Follow a request through threads, pools and transactions','Runtime architecture describes how application code acquires execution time and shared resources, how framework boundaries affect behavior, and how those resources are released during success and failure.','Know a Spring controller, SQL transaction and <a href="networking.html#reasoning-path">connection lifecycle</a>. Examples explain mechanisms; they are not a complete service.','Reason about thread exhaustion, transaction boundaries, connection budgets and blocking behavior before tuning.',[
s('problem','Follow one checkout request',p('A request reaches a controller, validates a DTO, invokes an application service, opens a database transaction, runs statements, commits and serializes a response. HTTP-client calls, executor handoffs and event listeners can insert additional boundaries. Draw where the transaction begins and where each resource is held. Latency accumulates in waits as well as execution.')+p('The servlet request thread and a database connection are different resources. A thread may wait for a connection, or hold one while waiting for a remote provider. Increasing the request executor can admit more waiting work without increasing database throughput. Instrument pool acquisition and statement time independently.')),
s('pools','Thread pools and connection pools',p('A bounded executor limits active tasks; a bounded queue limits waiting tasks. Rejection must have an explicit caller-visible or durable recovery policy. An unbounded queue can turn overload into delayed failure and memory pressure. HikariCP pools reusable database connections, but its maximum does not mean the database can execute that many expensive queries efficiently.')+p('Budget across the fleet: twenty pods with a pool maximum of twenty can request 400 connections, plus administration, migrations and other services. A larger pool can increase lock contention and query time, keeping connections occupied longer. Determine a useful operating point through workload measurement, not by setting every pool to the server limit.')),
s('transactions','Spring transaction boundaries',p('In ordinary proxy-based Spring transaction management, an external call through the proxy applies the transaction advice. Calling another annotated method on this bypasses that proxy boundary. The annotation expresses a policy; it does not make arbitrary code transactional. Use an explicitly proxied application-service boundary or a deliberate programmatic transaction when the control flow requires it.')+code('// Teaching fragment: caller invokes this Spring-managed service.\n@Transactional\npublic Reservation reserve(Command command) {\n    int changed = inventory.reserveIfAvailable(\n        command.sku(), command.positiveQuantity());\n    if (changed != 1) throw new InsufficientStock();\n    Reservation saved = reservations.insert(command);\n    outbox.append(saved.toEvent());\n    return saved;\n}\n// Call the payment provider outside this lock-holding transaction.')+p('The repositories must participate in the intended transaction manager and data source. Default rollback rules commonly differ for unchecked versus checked exceptions; configure and test the intended policy. Catching a database exception does not necessarily restore a usable transaction. JPA flush can surface a constraint violation later than the method that staged the write.')),
s('execution','Virtual threads, reactive code and blocking',p('Virtual threads make many waiting Java tasks cheaper to represent; they do not increase database connections, provider capacity or CPU. Do not use a pool of virtual threads as the concurrency control for a scarce dependency. Use explicit admission or permits around the resource while creating virtual threads according to the supported execution model.')+p('Reactive pipelines coordinate nonblocking work and backpressure when the participating components support it. Blocking a small event-loop pool can stall unrelated requests. Wrapping blocking JDBC in a reactive type does not change JDBC into nonblocking I/O. Conversely, a virtual-thread approach may simplify blocking code but still requires cancellation, context and resource limits. Choose for the actual workload and team, not as a universal throughput upgrade.')),
s('memory','Memory, GC and context propagation',p('A growing heap may reflect retained pending work, cache growth, oversized payloads or a leak. GC activity is evidence to interpret, not the root cause by definition. Compare allocation rate, live set after collection, pauses, queue lengths and payload distribution. Bound collections and request bodies before merely enlarging memory.')+p('MDC is commonly thread-bound. Executors, reactive pipelines and message boundaries need supported context capture, restoration and cleanup. ScopedValue can carry scoped in-process values but does not propagate HTTP headers or create distributed spans. Keep security context, trace context and business operation identity distinct and avoid leaking one request’s state into another.')),
s('worked','Worked diagnosis: low CPU, slow requests',p('Observe 90% database-pool occupancy, long acquisition waits and moderate query execution time. A code change placed an HTTP provider call inside @Transactional after the first query. Connections are now held across remote waits. Verify the timeline using tracing plus transaction/pool metrics, then move the remote step behind a durable state boundary without losing recovery identity.')+p('Bound provider waits, use a persisted payment state and reconcile unknown outcomes. Do not simply move the call earlier if that creates an unrecorded remote effect. Validate resource release on timeout and exception, mixed load across endpoints and total fleet connection usage.')),
s('interview','Runtime interview ladder',qa([['Foundational','Does @Transactional include a remote REST call?','It does not enlist an ordinary remote HTTP service in the local database commit. The remote effect can succeed even if the local transaction rolls back.'],['Intermediate','Why did self-invocation not start a new transaction?','Under normal proxy mode the call did not cross the transaction proxy. Refactor the boundary or use an explicit supported transaction mechanism; do not rely on an annotation that was never intercepted.'],['Advanced','Do virtual threads remove backpressure needs?','No. They reduce the cost of many waiting tasks, which can actually make it easier to overload finite dependencies. Bound admissions and scarce resources separately.'] ])),
s('references','Primary implementation reading',refs([['https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/annotations.html','Spring @Transactional','proxy interception, visibility and self-invocation.'],['https://github.com/brettwooldridge/HikariCP','HikariCP','pool configuration and acquisition behavior.'],['https://openjdk.org/jeps/444','Java virtual threads','execution model and resource limitations.'],['https://docs.spring.io/spring-framework/reference/web/webflux/new-framework.html','Spring WebFlux','nonblocking assumptions and concurrency.']]))
]),
guide('interview-workbook','Architecture Interview Workbook','Practice reasoning at increasing difficulty','An architecture interview answer is an argument: define the concept, connect it to a requirement, explain a mechanism, identify a failure boundary and defend the trade-off.','Read the linked V4 lessons first. Attempt an answer before opening the explanation; memorized product names do not satisfy the reasoning rubric.','Give precise answers, handle follow-ups and assess what is missing from your own reasoning.',[
s('problem','Use the answer ladder',p('Begin with a two-sentence definition and one concrete operation. Then extend the answer only as the question demands. A foundational question tests vocabulary; an intermediate question tests implementation under concurrency; a senior question tests crash windows and trade-offs; an architect question tests ownership, constraints and operations together.')+table(['Score','Evidence'],[['0','Names a product or pattern with no mechanism.'],['1','Defines the concept and a plausible happy path.'],['2','Explains implementation and the key concurrency/failure case.'],['3','Defends alternatives, scope, recovery, measurable validation and operational ownership.']])+p('The rubric assesses the reasoning shown, not years of experience. For each answer below, add a follow-up you would ask as an interviewer. A strong response explicitly distinguishes what is known from what must be clarified.')),
s('foundations','Foundational: define before naming libraries',qa([
['Foundational','What makes an operation idempotent?','Repeated application of the same intended operation has the same intended effect as applying it once. Responses need not be identical. For POST /orders, explain operation identity and atomic duplicate enforcement rather than assuming POST itself provides the guarantee. Follow-up: what happens when the same key carries a different payload?'],
['Foundational','Authentication versus authorization?','Authentication establishes identity under a trust model; authorization decides whether that identity may perform an action on a resource. A valid token does not grant access to every order. Follow-up: where is tenant ownership checked for an export?'],
['Foundational','Cache versus read replica?','Both can serve copies, but an application cache reuses selected answers with explicit key/freshness policy, while a read replica maintains a database copy under its replication protocol. Both can be stale. Follow-up: which path can confirm a newly committed order?'],
['Foundational','Latency versus throughput?','Latency is the time for an operation over a stated boundary; throughput is completed operations per unit time. Higher concurrency can improve throughput until a resource saturates and waiting increases. Follow-up: which measurements distinguish CPU work from pool waiting?'] ])),
s('implementation','Intermediate: make the mechanism concrete',qa([
['Intermediate','How do you prevent two buyers taking the last item?','Use an authoritative conditional mutation such as UPDATE inventory SET available=available-:qty WHERE sku=:sku AND available>=:qty with positive validated quantity. Check affected rows and commit the reservation in the same transaction. Follow-up: how is a repeated reservation request recognized?'],
['Intermediate','How do you avoid lost updates in a REST API?','Expose a version or strong validator with a defined representation scope; require a conditional update and atomically compare the expected version at the storage boundary. Return the documented precondition failure when stale. Follow-up: what does the client do after reading the new state?'],
['Intermediate','Why can cursor pagination still repeat or omit results?','The cursor must encode stable ordering and a unique tie-breaker, but changing sort fields, deletions and dataset evolution still affect traversal. Define whether the contract is a live traversal or a snapshot. Follow-up: how would an export establish a consistent view?'],
['Intermediate','How would Spring publish an event safely after an order commit?','Store order and outbox in the same local transaction, then relay committed rows. A relay can republish after a crash, so consumers need repeat-safe processing. An in-memory after-commit callback alone is not a durable publication ledger. Follow-up: what protects an external fulfillment effect?'] ])),
s('senior','Senior: walk the failure window',qa([
['Senior','The payment provider succeeded but the client timed out. Now what?','Treat the outcome as unknown until verified. Keep the provider operation identity, query or retry according to its idempotency contract and persist reconciliation progress. A fresh payment key risks another charge. Follow-up: what if the provider retention window has elapsed?'],
['Senior','Why did adding replicas increase errors?','Test whether a shared bottleneck was amplified: total pool capacity, retries, hot locks or dependency quotas. Compare fleet admissions with useful completions and dependency saturation. Bound global pressure before adding callers. Follow-up: what capacity remains when one zone fails?'],
['Senior','A message repeatedly fails deserialization. Should it be skipped?','Preserve the event and identity, isolate the incompatible population and establish ordering requirements. Skipping can allow later aggregate events to overtake a prerequisite. Repair a compatible reader and replay under a durable deduplication/state protocol. Follow-up: what proves business recovery?'],
['Senior','How do you roll back a release that wrote new data states?','Check whether old code can read and act on those states. Image rollback does not reverse data. Disable unsafe new writes if supported, deploy compatible readers or forward repair, then reconcile affected records. Follow-up: what would have prevented the rollout hazard?'] ])),
s('worked','Architect: a complete checkout prompt',p('<strong>Prompt:</strong> design checkout for a multi-tenant shop with a flash sale, external payments and asynchronous fulfillment. Browsing can be stale, overselling is forbidden, and an unknown payment must not cause a second charge. Ask for actual workload, latency, completion and recovery targets before choosing components.')+p('<strong>Expected reasoning:</strong> establish authoritative inventory and payment state; reserve atomically with repeat-safe identity; commit outbox with local facts; invoke the provider with stable identity outside lock-holding transactions; persist unknown outcomes; deduplicate local consumer effects and reconcile remote fulfillment. Isolate tenants, cap admissions, define expiry/late-success policy and measure completion age.')+p('<strong>Strong follow-ups:</strong> Where is the last-item claim serialized? Who wins payment versus reservation expiry? What if the provider has no idempotency or lookup contract? Which read may be stale? What state survives a region loss? A strong answer may conclude a guarantee cannot be met under a stated provider constraint and propose a business or integration change.')+qa([['Architect','How would you evaluate two technically plausible designs?','Compare invariant coverage, intermediate states, failure recovery, peak/failure capacity, security and team operating cost. Require evidence at the critical boundaries, not only a clean topology diagram.'],['Architect','What if the business requires instant completion during every dependency outage?','Expose the contradiction: a final authoritative remote result may be unavailable. Offer durable acceptance with pending state, degraded scope or a revised availability guarantee. Do not promise an outcome that the system cannot establish.'] ])),
s('references','Review the mechanisms behind the answers',p('Use <a href="decision-guides.html#worked">the decision record</a>, <a href="failure-case-studies.html#duplicate-payment">the duplicate-payment investigation</a>, <a href="capacity-cost.html#concurrency">capacity calculations</a> and <a href="java-spring-internals.html#transactions">Spring transaction boundaries</a> to strengthen weak answers. Return after studying and explain the same solution without relying on a product name.'))
]),
guide('migration-modernization','Migration & Modernization','Change the system while old and new versions coexist','A migration is a controlled transition of behavior, state or ownership between implementations. Correctness depends on compatibility during overlap, reconciliation of changes and a defined rollback or forward-repair boundary.','Read <a href="deployment-runtime.html#reasoning-path">mixed versions</a>, <a href="databases.html#transactions">transaction boundaries</a> and <a href="disaster-recovery.html#reasoning-path">recovery</a>.','Plan schema, runtime, database and service migrations with evidence-based cutover gates.',[
s('problem','Inventory the change before moving anything',p('Begin with consumers, data writers, scheduled jobs, runtime dependencies, message schemas and operational tooling. A Java upgrade changes more than a compiler target; a database migration changes more than a connection string. Capture the current contract and failure behavior so improvements do not silently break existing consumers.')+p('Separate reversible routing/configuration changes from irreversible or difficult-to-reverse data changes. Define which source owns each fact at every stage. A rollback plan that says “point back to the old database” is incomplete if new writes exist only in the target.')),
s('schema','Expand, migrate, verify, contract',p('Suppose full_name becomes given_name and family_name. Add nullable new columns first and deploy readers that tolerate incomplete backfill. Define the transformation honestly: many names cannot be split reliably by spaces. Backfill in bounded, restartable batches using stable progress identity and conditional updates so a concurrent edit is not overwritten.')+p('During overlap, define which representation is authoritative and how old writers remain compatible. When all readers and writers are upgraded, verify reconciliation and stop the old path. Remove old columns only after the rollback/support window ends. If two representations are stored, their consistency is a protocol to own, not an incidental implementation detail.')+warn('Do not treat a successful deployment as permission to drop old columns immediately. Old instances, batch jobs, delayed messages and rollback paths may still require them.')),
s('runtime','Java and Spring upgrade sequence',p('Inventory application server support, bytecode targets, libraries, reflection, removed APIs, build plugins, agents, TLS providers and test tooling. Choose a supported target combination using the actual vendor support matrix. Upgrading Spring and changing the deployment runtime at once can make failures harder to isolate; stage changes where compatibility allows.')+p('Compile and test business paths, integration protocols, serialization, security, database behavior and startup/shutdown. Benchmark representative CPU, allocation, latency and memory with comparable limits. A lower GC pause in a microbenchmark does not prove a safe production migration. Canary the new runtime, retain compatible images and define observable rollback triggers.')+p('If an application server does not support the required JDK, evaluate a supported framework/JDK combination, a server upgrade or moving the application to an independently supported runtime. Do not assume putting newer bytecode in a container makes the host application server support it.')),
s('data','Database copy and catch-up',p('An online migration usually needs a consistent baseline plus a position from which subsequent changes can be captured. A bulk copy without a matching change stream can miss or reorder updates during the scan. Preserve deletions, transaction/order semantics required by the target and schema transformations. Measure lag by relevant source positions and business freshness, not merely whether a process is running.')+p('Verify counts, keys, sampled/full checksums where meaningful, query results and critical invariants. Define a controlled write-ownership switch using fencing or a brief write pause when necessary. “Zero downtime” must specify what readers and writers can observe and whether bounded retries or deferred acceptance are allowed.')),
s('services','Extract a service with a strangler route',p('Choose one cohesive behavior and place an explicit interface around it. Route a limited operation or tenant population to the new implementation while retaining ownership rules. Shadow reads can compare outputs if authorization, side effects and sensitive data are controlled. Shadow writes to real business providers are unsafe without a separate harmless environment.')+p('Avoid long-lived uncontrolled dual writes. If local commit and remote publish are required, use a durable handoff and reconciliation protocol. Move data ownership deliberately; leaving every service able to mutate the same tables undermines independent boundaries. Retire old routing and jobs only when no supported path still depends on them.')),
s('worked','Worked cutover: new account and new database cluster',p('Assume one authoritative writer and a target cluster in a new account. Establish identity/network/secret access, copy a consistent baseline, capture changes, apply idempotently and compare critical records. Rehearse full recovery before scheduling cutover. Freeze schema changes or handle them through an explicit migration-compatible process.')+p('At cutover, stop or fence source writers, record the final change position, wait for target application and invariant checks, then enable the target writer and redirect traffic. If the target is unhealthy before accepting writes, routing back may be straightforward. After target-only writes begin, rollback requires reverse synchronization, a bounded write pause plus merge/reconciliation, or forward repair. Never enable both writers merely to reduce downtime.')+p('Gate completion on business paths, queue consumers, scheduled jobs, access control and telemetry in the new account. Record unresolved differences and retain the source according to the recovery plan. Cross-account DNS success does not prove that IAM, KMS, network policies and background jobs all function.')),
s('interview','Migration interview',qa([['Intermediate','Why is dual write not an atomic migration strategy?','Two independent writes can fail separately. Define durable capture, ordering, retries and reconciliation, or constrain the transition so one authority remains clear.'],['Advanced','When does rollback become a data problem?','As soon as the new path commits facts the old path lacks or cannot interpret. Define that boundary before cutover and prepare reverse catch-up or forward repair with business reconciliation.'] ])),
s('references','Primary migration reading',refs([['https://docs.aws.amazon.com/dms/latest/userguide/Welcome.html','AWS DMS','supported migration/CDC capabilities and endpoint limitations.'],['https://docs.spring.io/spring-boot/reference/web/graceful-shutdown.html','Spring Boot graceful shutdown','request draining and supported runtime behavior; verify against the chosen release.'],['https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/strangler-fig.html','Strangler fig pattern','incremental replacement and routing boundaries.']]))
]),
guide('revision-toolkit','Revision & Learning Toolkit','Retrieve the reasoning, then check the answer','Effective revision retrieves a concept from memory, applies it to a changed scenario and corrects misunderstandings using explicit feedback. These tools support review; progress is stored only in this browser when available.','Begin with <a href="lessons.html">the V4 learning path</a>. Complete a topic’s reasoning section before marking it understood.','Identify weak concepts, navigate prerequisites and recall failure boundaries without rereading every page.',[
s('problem','A practical review cycle',p('Read one lesson, close it and explain the main operation in plain language. Name the invariant, the simplest implementation, its failure window and the chosen mechanism. Then compare your explanation with the answered checkpoints. Record a gap such as “I cannot explain lease expiry” rather than marking a whole subject vaguely incomplete.')+p('A suggested cadence is next-day recall, another review later in the week and a later scenario-based review. Adjust it to your recall rather than treating a schedule as proof of learning. The checklist below is browser-local, is not an assessment and does not sync across devices.')+`<div id="review-status" role="status" aria-live="polite"></div><div id="review-checklist"></div><button type="button" id="reset-review">Reset review marks</button>`),
s('prerequisites','Follow the dependency map',table(['Before studying','Be able to explain','Then connect to'],[['Networking → API Design → Security','Request path, contract, identity and permission','Correct operation before distributed behavior.'],['Scalability → Databases → Caching','Finite capacity, authoritative mutations and copies','Freshness versus throughput.'],['Messaging → Consistency → Microservices','Durable handoff, observations and ownership','Intermediate states and recovery.'],['Rate Limiting → Reliability → Deployment','Admission, deadlines and overlapping versions','Surviving overload and change.'],['Replication → DR → Pipelines → Observability','Ownership, recovery and derived state','Diagnosis across incomplete evidence.']])+p('This is a prerequisite guide, not a requirement to read every page before doing useful work. Follow the specific links when a term blocks your understanding. Return to <a href="decision-guides.html">decision guides</a> once you can describe the alternatives without product names.')),
s('glossary','A focused glossary of commonly blurred terms',`<label for="glossary-filter">Find a term</label><input id="glossary-filter" type="search" placeholder="Try deadline, outbox, RPO…" aria-controls="glossary-entries"><p id="glossary-count" role="status" aria-live="polite"></p><div id="glossary-entries">`+[
['Invariant','A condition that must hold after every allowed state transition. A target permits a measured error budget; an invariant defines a forbidden outcome.'],['Atomicity','A defined group of changes commits together or does not commit. Specify which resources share that boundary.'],['Isolation','Rules governing concurrent transaction observations and permitted anomalies. A transaction annotation alone does not specify every business-safe protocol.'],['Consistency','The observations or histories an operation permits. State the model and scope; do not confuse replica freshness with multi-system atomicity.'],['Idempotency','Repeating one intended operation preserves its intended effect. Recognizing identity and enforcing it atomically are separate implementation tasks.'],['Deadline','The latest acceptable completion time across a defined operation. Individual timeout budgets should account for remaining time.'],['Backpressure','A mechanism for signaling or limiting work according to downstream demand/capacity. It requires participating boundaries and does not create capacity.'],['Outbox','A durable publication intent committed with local business changes, then relayed. Relaying can repeat and does not include arbitrary remote effects.'],['Inbox','A durable consumer-side receipt/identity record used with a local mutation to make repeat processing safe within that boundary.'],['Fencing','Rejecting actions from an obsolete owner using authoritative ownership/version evidence. Lease expiry alone does not stop old execution.'],['RPO','Recovery point objective: the tolerated data-loss window. Measure it against recoverable business facts, including external effects.'],['RTO','Recovery time objective: the tolerated duration to restore a defined usable service, including dependencies and reconciliation.'],['SLI','A precisely defined measurement of service behavior, with eligible events and good/bad criteria.'],['SLO','A target for an SLI over a stated window. Acceptance and eventual business completion can require separate indicators.'],['Projection','A derived representation maintained from authoritative facts. Its ordering, freshness, deletion and replay policies must be explicit.'],['Cardinality','The number of distinct values/combinations in a dataset or telemetry dimension. Unbounded metric labels can create unbounded series.'],['Optimistic concurrency','A mutation commits only if an expected version or condition still holds. Handle conflicts explicitly rather than overwriting newer state.'],['Compensation','A business recovery action after a committed step. It may not perfectly undo the original effect and can itself fail.']
].map(([t,d])=>`<article class="glossary-entry"><h3>${t}</h3>${p(d)}</article>`).join('')+'</div>'),
s('comparisons','Recall the distinction',table(['Pair','Key distinction','Test yourself'],[['Timeout / failed effect','Waiting ended / business action did not happen','Can the provider have charged already?'],['Cache / authority','Reusable copy / fact used to enforce a rule','May stale data authorize a purchase?'],['Rate / concurrency','Arrivals per time / work currently active','What changes when service time increases?'],['Trace ID / operation key','Observability identity / repeat-safe business identity','Which one prevents a second mutation?'],['Replica / backup','Operational copy / recovery representation','What happens after a bad delete propagates?'],['Rollback / compensation','Revert uncommitted local changes / business recovery after commit','Can the customer already have seen the effect?'] ])),
s('worked','Self-check: the disappearing response',p('A customer creates an order. The database commits, the connection drops, and the customer retries. Explain the possible states without assuming the first request failed. Identify the durable operation identity, payload mismatch policy, concurrent duplicate guard and response reconstruction mechanism.')+qa([['Intermediate','What should the answer contain?','A stable scoped key, a fingerprint or equivalent mismatch rule, atomic enforcement with the local order effect, and a documented response for completed/in-progress/conflicting requests. A lookup can recover an already committed result. If payment is external, analyze that provider boundary separately.'],['Advanced','Change the scenario: the retry arrives after retention expires.','The deduplication guarantee may no longer apply. Business uniqueness and provider reconciliation can still matter. Define retention relative to real retry/replay windows and document what happens outside it rather than implying infinite protection.'] ])),
s('interview','Explain it without notes',p('Choose a weak concept and answer: What does it mean? Why is it needed? Which failure exposes it? Where is it enforced? What remains unprotected? What test would disprove the design? Use the <a href="interview-workbook.html#problem">interview rubric</a> to assess the answer.')),
s('references','Return to the source of confusion',p('Use the official references attached to each lesson when an implementation guarantee matters. Use <a href="failure-case-studies.html">failure cases</a> to test understanding and <a href="migration-modernization.html">migration scenarios</a> to check whether the design still works while state and versions change.'))
])
];

const guideIntroductions={"decision-guides": "Start with an invariant, compare the mechanisms that can enforce it, and write a decision you can defend through a crash.", "failure-case-studies": "Investigate four fictional incidents step by step: cache storms, duplicate payments, stranded fulfillment and mixed-version releases.", "capacity-cost": "Work from daily demand to peak load, simultaneous work, failure headroom, durable bytes and a transparent cost model.", "java-spring-internals": "Open the implementation boundary: trace execution, connection acquisition, local commits and resource release in a Spring service.", "interview-workbook": "Attempt the questions before opening the answers. Progress from definitions to concurrency, crash recovery and an architect-level checkout argument.", "migration-modernization": "Follow an overlapping-version change from inventory and compatibility through backfill, cutover and the point where rollback needs data reconciliation.", "revision-toolkit": "Review prerequisites, search commonly confused terms, test your recall and keep a browser-local checklist of the explanations you can give."};
for(const guide of practiceGuides)guide.intro=guideIntroductions[guide.slug];
